def make_steps(names, failing=(), failing_undo=()):
    """Steps that record what runs in `events`. Actions named in `failing` raise after being recorded; so do compensations named in `failing_undo`."""
    events = []
    steps = []
    for name in names:
        def action(name=name):
            events.append(f"do {name}")
            if name in failing:
                raise RuntimeError(f"{name} failed")

        def undo(name=name):
            events.append(f"undo {name}")
            if name in failing_undo:
                raise RuntimeError(f"undoing {name} failed")

        steps.append((name, action, undo))
    return steps, events

