def run_saga(steps):
    completed = []                       # the steps whose action succeeded, oldest first
    failed_step = None
    for step in steps:
        name, action, _ = step
        try:
            action()
        except Exception:
            failed_step = name
            break                        # later steps never run
        completed.append(step)

    compensated, compensation_failed = [], []
    if failed_step is not None:                          # when every action succeeded there is nothing to undo
        for name, _, compensation in reversed(completed):    # newest first; the failed step is not in `completed`
            try:
                compensation()
            except Exception:
                compensation_failed.append(name)         # record it, then keep undoing the rest
            else:
                compensated.append(name)

    if failed_step is None:
        status = "completed"
    elif compensation_failed:
        status = "rollback_failed"
    else:
        status = "rolled_back"
    return {"status": status, "failed_step": failed_step, "compensated": compensated, "compensation_failed": compensation_failed}
